firmware:
#include <ESP32Servo.h>

const int VERT_PIN = 34;
const int SERVO_PIN = 13;
Servo servo;
int angle = 90;
unsigned long lastPrint = 0;

void setup() {
  Serial.begin(115200);
  servo.attach(SERVO_PIN);
}

void loop() {
  int raw = analogRead(VERT_PIN);
  angle = map(raw, 0, 4095, 0, 180);
  servo.write(angle);
  if (millis() - lastPrint >= 200) {
    lastPrint = millis();
    Serial.print("ANGLE=");
    Serial.println(angle);
  }
  delay(50);
}
